package com.spinplayer.app;
import android.app.DownloadManager;import android.content.*;import android.database.Cursor;import android.os.Environment;import android.net.Uri;import org.json.*;import org.schabi.newpipe.extractor.stream.AudioStream;import java.io.*;import java.net.*;import java.util.*;
public final class OnlineDownloads {
 static JSONArray load(Context c){try{return new JSONArray(c.getSharedPreferences("spin",0).getString("downloads","[]"));}catch(Exception e){return new JSONArray();}}
 static void save(Context c,JSONArray list){c.getSharedPreferences("spin",0).edit().putString("downloads",list.toString()).apply();}
 static String clean(String s){String value=s.replaceAll("[\\\\/:*?\"<>|\\p{Cntrl}]","_").trim();return value.isEmpty()?"Без названия":value.substring(0,Math.min(90,value.length()));}
 public static synchronized String enqueue(Context c,String raw)throws Exception{JSONObject job=new JSONObject(raw);OnlineExtractor.validate(job.getString("url"));JSONArray list=load(c);for(int i=0;i<list.length();i++){JSONObject old=list.getJSONObject(i);if(job.getString("url").equals(old.optString("url"))&&!"failed".equals(old.optString("status")))throw new IOException("Эта запись уже в очереди или скачана");}job.remove("formats");job.put("id",System.currentTimeMillis()*1000L+(System.nanoTime()%1000)).put("engine",YandexCatalog.accepts(job.getString("url"))?"yandex":SpotifyCatalog.accepts(job.getString("url"))?"spotify-match":"yt-dlp").put("format",job.optString("formatKey","best")).put("status","pending").put("path","Music/SPIN/"+clean(job.optString("artist"))+"/"+clean(job.optString("album")));list.put(job);save(c,list);c.startForegroundService(new Intent(c,DownloadService.class));return list.toString();}
 public static synchronized String state(Context c){JSONArray list=load(c);for(int i=0;i<list.length();i++){JSONObject j=list.optJSONObject(i);try{if(!j.has("engine")&&!j.optBoolean("imported")&&!j.optBoolean("synthetic")){c.getSystemService(DownloadManager.class).remove(j.optLong("id"));j.put("status","failed").put("synthetic",true).put("error","Старый загрузчик заменён на yt-dlp. Нажми «Повторить».");}}catch(Exception ignored){}}if(DownloadService.instance==null){for(int i=0;i<list.length();i++){JSONObject j=list.optJSONObject(i);try{if("running".equals(j.optString("status")))j.put("status","failed").put("error","Загрузка прервана. Нажми «Повторить».");}catch(Exception ignored){}}save(c,list);}return list.toString();}
 static synchronized JSONObject next(Context c){JSONArray a=load(c);for(int i=0;i<a.length();i++){JSONObject j=a.optJSONObject(i);if("pending".equals(j.optString("status"))||"waiting".equals(j.optString("status")))return j;}return null;}
 static synchronized boolean exists(Context c,long id){JSONArray a=load(c);for(int i=0;i<a.length();i++)if(a.optJSONObject(i).optLong("id")==id)return true;return false;}
 static synchronized void update(Context c,long id,String status,String error){JSONArray a=load(c);for(int i=0;i<a.length();i++)try{JSONObject j=a.getJSONObject(i);if(j.optLong("id")==id)j.put("status",status).put("error",error);}catch(Exception ignored){}save(c,a);}
 static synchronized void progress(Context c,long id,long bytes,long total,double speed){JSONArray a=load(c);for(int i=0;i<a.length();i++)try{JSONObject j=a.getJSONObject(i);if(j.optLong("id")==id)j.put("bytes",bytes).put("total",total).put("speed",speed);}catch(Exception ignored){}save(c,a);}
 static synchronized void audioSource(Context c,long id,String url){JSONArray a=load(c);for(int i=0;i<a.length();i++)try{JSONObject j=a.getJSONObject(i);if(j.optLong("id")==id)j.put("audioSourceUrl",url);}catch(Exception ignored){}save(c,a);}
 static synchronized void completed(Context c,long id,Uri uri,long bytes,long duration,long elapsed)throws Exception{JSONArray a=load(c);for(int i=0;i<a.length();i++){JSONObject j=a.getJSONObject(i);if(j.optLong("id")==id){j.put("status","done").put("completedAt",System.currentTimeMillis()).put("bytes",bytes).put("total",bytes).put("duration",duration/1000.0).put("elapsedMs",elapsed);importFile(c,j,uri);}}save(c,a);}
 static void importFile(Context c,JSONObject job,Uri uri)throws Exception{synchronized(MusicLibrary.class){JSONArray library=MusicLibrary.load(c);int id=MusicLibrary.id(uri.toString());boolean exists=false;for(int j=0;j<library.length();j++)if(library.getJSONObject(j).optInt("id")==id)exists=true;if(!exists){JSONObject t=new JSONObject().put("id",id).put("name",job.optString("name")).put("artist",job.optString("artist")).put("album",job.optString("album")).put("duration",job.optDouble("duration")).put("uri",uri.toString()).put("native",true).put("number",job.optInt("number",0)).put("cover","app-cover.svg").put("sourceUrl",job.optString("catalogUrl",job.optString("url"))).put("audioSourceUrl",job.optString("audioSourceUrl",job.optString("url"))).put("year",job.optString("year"));File art=new File(c.getFilesDir(),"art/online-"+Integer.toHexString(job.optString("cover").hashCode())+".jpg");if(art.exists())t.put("cover","art/"+art.getName());library.put(t);MusicLibrary.save(c,library);}job.put("imported",true);}}
 public static synchronized String failure(Context c,String request,String error){JSONArray list=load(c);try{JSONObject job=new JSONObject(request);job.remove("formats");job.put("id",-(System.nanoTime()%9000000000000000L)).put("status","failed").put("synthetic",true).put("error",error);list.put(job);save(c,list);}catch(Exception ignored){}return list.toString();}
 public static synchronized String cancel(Context c,long id){JSONArray a=load(c),b=new JSONArray();for(int i=0;i<a.length();i++)if(a.optJSONObject(i).optLong("id")!=id)b.put(a.optJSONObject(i));save(c,b);return b.toString();}
}
